function parseObject(value) {
  if (value && typeof value === 'object') {
    return value;
  }

  if (typeof value !== 'string' || !value.trim()) {
    return {};
  }

  try {
    return JSON.parse(value);
  } catch {
    return {};
  }
}

function normalizeArray(value) {
  if (Array.isArray(value)) {
    return value
      .map((entry) => String(entry || '').trim())
      .filter(Boolean);
  }

  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);

      if (Array.isArray(parsed)) {
        return parsed
          .map((entry) => String(entry || '').trim())
          .filter(Boolean);
      }
    } catch {
      return value
        .split(',')
        .map((entry) => entry.trim())
        .filter(Boolean);
    }
  }

  return [];
}

function parseSalaryAmount(rawValue, hasThousandsMarker) {
  let number = Number(
    String(rawValue || '')
      .replace(/\u00a0/g, ' ')
      .replace(/\s/g, '')
      .replace(',', '.')
  );

  if (!Number.isFinite(number)) {
    return null;
  }

  if (hasThousandsMarker && number < 1000) {
    number *= 1000;
  }

  if (number < 10000 || number > 2000000) {
    return null;
  }

  return Math.round(number);
}

function extractUpperBounds(text) {
  const source = String(text || '')
    .replace(/\u00a0/g, ' ')
    .toLowerCase();

  const values = [];

  const rangePattern =
    /(\d[\d\s]*(?:[.,]\d+)?)\s*((?:тыс(?:\.|яч[аи]?)?|k))?\s*(?:-|–|—|до)\s*(\d[\d\s]*(?:[.,]\d+)?)\s*((?:тыс(?:\.|яч[аи]?)?|k))?(?:\s*(?:(?:руб(?:\.|ля|лей)?|rur)|₽))?/gi;

  for (const match of source.matchAll(rangePattern)) {
    const hasThousands = Boolean(match[2] || match[4]);

    const upper = parseSalaryAmount(
      match[3],
      Boolean(match[4]) || hasThousands
    );

    if (upper !== null) {
      values.push(upper);
    }
  }

  const upperLimitPattern =
    /(?:до|максимум|max)\s*(\d[\d\s]*(?:[.,]\d+)?)\s*((?:тыс(?:\.|яч[аи]?)?|k))?(?:\s*(?:(?:руб(?:\.|ля|лей)?|rur)|₽))?/gi;

  for (const match of source.matchAll(upperLimitPattern)) {
    const upper = parseSalaryAmount(match[1], Boolean(match[2]));

    if (upper !== null) {
      values.push(upper);
    }
  }

  return values;
}

function extractSalaryContexts(descriptionValue) {
  const description = String(descriptionValue || '')
    .replace(/\u00a0/g, ' ')
    .replace(/\s+/g, ' ')
    .toLowerCase();

  const markerPattern =
    /зарплат|заработн|оклад|доход|оплат[аы]|вознагражден|вилк/gi;

  const contexts = [];

  for (const match of description.matchAll(markerPattern)) {
    const start = Math.max(0, match.index - 60);
    const end = Math.min(description.length, match.index + 220);

    contexts.push(description.slice(start, end));
  }

  return contexts;
}

function extractKnownSalaryUpperBound(
  salaryValue,
  descriptionValue
) {
  const salary = String(salaryValue || '')
    .replace(/\u00a0/g, ' ')
    .replace(/\s+/g, ' ')
    .toLowerCase()
    .trim();

  const salaryIsUnknown =
    !salary ||
    /не указана|не указан|по договоренности|обсуждается/.test(
      salary
    );

  if (!salaryIsUnknown) {
    const unsupportedCurrency =
      /usd|eur|доллар|евро|\$|€/.test(salary) &&
      !/(?:руб|rur|₽)/.test(salary);

    if (unsupportedCurrency) {
      return null;
    }

    if (
      /за час|в час|почасов|за смену|за проект/.test(salary)
    ) {
      return null;
    }

    const isLowerBoundOnly =
      /^\s*от\s*\d/i.test(salary) &&
      !/до\s*\d/i.test(salary) &&
      !/(?:-|–|—)\s*\d/i.test(salary);

    if (isLowerBoundOnly) {
      return null;
    }

    const structuredBounds = extractUpperBounds(salary);

    if (structuredBounds.length > 0) {
      return Math.max(...structuredBounds);
    }

    const fixedPattern =
      /(\d[\d\s]*(?:[.,]\d+)?)\s*((?:тыс(?:\.|яч[аи]?)?|k))?(?:\s*(?:(?:руб(?:\.|ля|лей)?|rur)|₽))/gi;

    const fixedValues = [];

    for (const match of salary.matchAll(fixedPattern)) {
      const fixed = parseSalaryAmount(
        match[1],
        Boolean(match[2])
      );

      if (fixed !== null) {
        fixedValues.push(fixed);
      }
    }

    if (fixedValues.length > 0) {
      return Math.max(...fixedValues);
    }

    return null;
  }

  const contextualBounds = [];

  for (const context of extractSalaryContexts(descriptionValue)) {
    contextualBounds.push(...extractUpperBounds(context));

    const fixedPattern =
      /(\d[\d\s]*(?:[.,]\d+)?)\s*((?:тыс(?:\.|яч[аи]?)?|k))?(?:\s*(?:(?:руб(?:\.|ля|лей)?|rur)|₽))/gi;

    for (const match of context.matchAll(fixedPattern)) {
      const fixed = parseSalaryAmount(
        match[1],
        Boolean(match[2])
      );

      if (fixed !== null) {
        contextualBounds.push(fixed);
      }
    }
  }

  if (contextualBounds.length === 0) {
    return null;
  }

  return Math.max(...contextualBounds);
}

const hardBlockingReasons = new Set([
  'salary_below_minimum',
  'vacancy_archived',
  'vacancy_unavailable',
]);

const decisionPriority = {
  recommend: 0,
  review: 1,
  reject: 2,
};

const eligible = [];

for (const item of $input.all()) {
  const vacancy = { ...item.json };
  const analysis = parseObject(vacancy.analysis_json);

  const evaluation =
  analysis.evaluation &&
  typeof analysis.evaluation === 'object'
    ? analysis.evaluation
    : analysis;

  const recommendedResume = String(
    vacancy.recommended_resume ||
      evaluation.recommended_resume ||
      'none'
  );

  if (
    recommendedResume !== 'ai_automation' &&
    recommendedResume !== 'it_infrastructure'
  ) {
    continue;
  }

  if (
    typeof vacancy.cover_letter === 'string' &&
    vacancy.cover_letter.trim()
  ) {
    continue;
  }

  const blockingReasons = [
    ...new Set([
      ...normalizeArray(evaluation.blocking_reasons),
      ...normalizeArray(vacancy.blocking_reasons),
    ]),
  ];

  const salaryUpperBound = extractKnownSalaryUpperBound(
    vacancy.salary,
    vacancy.description_text
  );

  const minimumSalary =
    recommendedResume === 'ai_automation' ? 120000 : 100000;

  if (
    salaryUpperBound !== null &&
    salaryUpperBound < minimumSalary &&
    !blockingReasons.includes('salary_below_minimum')
  ) {
    blockingReasons.push('salary_below_minimum');
  }

  const hasHardBlocker = blockingReasons.some((reason) =>
    hardBlockingReasons.has(reason)
  );

  if (hasHardBlocker) {
    continue;
  }

  const score = Number.isFinite(Number(vacancy.score))
    ? Number(vacancy.score)
    : Number(evaluation.score || 0);

  const decision = String(
    evaluation.decision ||
      (score >= 75 ? 'recommend' : score >= 60 ? 'review' : 'reject')
  );

  vacancy.letter_analysis = evaluation;
  vacancy.letter_recommended_resume = recommendedResume;
  vacancy.letter_score = score;
  vacancy.letter_decision = decision;
  vacancy.letter_blocking_reasons = blockingReasons;
  vacancy.detected_salary_upper_bound = salaryUpperBound;

  eligible.push(vacancy);
}

eligible.sort((a, b) => {
  const decisionDifference =
    (decisionPriority[a.letter_decision] ?? 3) -
    (decisionPriority[b.letter_decision] ?? 3);

  if (decisionDifference !== 0) {
    return decisionDifference;
  }

  if (b.letter_score !== a.letter_score) {
    return b.letter_score - a.letter_score;
  }

  return String(b.published_at || '').localeCompare(
    String(a.published_at || '')
  );
});

return eligible.map((vacancy) => ({
  json: vacancy,
}));

const vacancy = { ...$json };
const apiKey = String($env.OPENROUTER_API_KEY || '').trim();

if (!apiKey) {
  throw new Error('OPENROUTER_API_KEY is not configured');
}

if (
  !vacancy.openrouter_request ||
  typeof vacancy.openrouter_request !== 'object'
) {
  throw new Error(
    `Missing OpenRouter request for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

const retryableStatuses = new Set([
  429,
  500,
  502,
  503,
  504,
]);

const maxHttpAttempts = 2;

async function sendRequest(request) {
  let response = null;
  let lastStatus = 0;

  for (
    let attempt = 1;
    attempt <= maxHttpAttempts;
    attempt += 1
  ) {
    try {
      response = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://openrouter.ai/api/v1/chat/completions',
        headers: {
          Authorization: `Bearer ${apiKey}`,
          'Content-Type': 'application/json',
        },
        body: request,
        json: true,
        timeout: 120000,
      });

      break;
    } catch (error) {
      lastStatus = Number(
        error?.statusCode ||
        error?.response?.statusCode ||
        error?.response?.status ||
        0
      );

      const canRetry =
        attempt < maxHttpAttempts &&
        retryableStatuses.has(lastStatus);

      if (!canRetry) {
        throw new Error(
          `OpenRouter request failed for vacancy ${
            vacancy.vacancy_id || 'unknown'
          }; HTTP ${lastStatus || 'unknown'}`
        );
      }

      const delayMs = lastStatus === 429 ? 5000 : 2000;

      await new Promise((resolve) => {
        setTimeout(resolve, delayMs);
      });
    }
  }

  if (!response || typeof response !== 'object') {
    throw new Error(
      `Empty OpenRouter response for vacancy ${
        vacancy.vacancy_id || 'unknown'
      }`
    );
  }

  return response;
}

function extractStructuredResult(response) {
  const rawContent =
    response?.choices?.[0]?.message?.content;

  if (
    typeof rawContent !== 'string' ||
    !rawContent.trim()
  ) {
    return null;
  }

  const cleanedContent = rawContent
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    const parsed = JSON.parse(cleanedContent);

    if (
      !parsed ||
      typeof parsed !== 'object' ||
      Array.isArray(parsed)
    ) {
      return null;
    }

    return parsed;
  } catch {
    return null;
  }
}

function containsInternalProjectName(value) {
  return /AI Content Studio|AICS|MIKISSKIDS|Элиор/iu.test(
    String(value || '')
  );
}

function containsMetaPhrase(value) {
  const text = String(value || '').trim();

  const patterns = [
    /(?:^|[^\p{L}\p{N}_])(?:этот\s+опыт|такой\s+опыт|такой\s+подход|эти\s+навыки)(?![\p{L}\p{N}_])/iu,
    /(?:^|[^\p{L}\p{N}_])это\s+(?:(?:напрямую|непосредственно|явно)\s+)?(?:подтвержда|показыва|да[её]т|дал[аои]?|связано|близко|пересека)[\p{L}\p{N}_]*/iu,
    /(?:^|[^\p{L}\p{N}_])что\s+(?:(?:напрямую|непосредственно|явно)\s+)?(?:подтвержда|показыва|помога|позволя|близк|связан|пересека|да[её]т|дал[аои]?)[\p{L}\p{N}_]*/iu,
    /(?:^|[.!?]\s+|\n+)в\s+вакансии\s+мне\s+близк[\p{L}]*/iu,
  ];

  return patterns.some((pattern) => pattern.test(text));
}

let response = await sendRequest(
  vacancy.openrouter_request
);

const primaryResult = extractStructuredResult(response);

const primaryStrategy = String(
  primaryResult?.letter_strategy || ''
).trim();

const primaryText = String(
  primaryResult?.cover_letter ||
  primaryResult?.letter ||
  ''
).trim();

const needsCorrection =
  primaryResult !== null &&
  primaryStrategy !== 'omit' &&
  (
    !primaryText ||
    containsMetaPhrase(primaryText) ||
    containsInternalProjectName(primaryText)
  );

if (needsCorrection) {
  const firstContent = String(
    response?.choices?.[0]?.message?.content || ''
  ).trim();

  const correctionInstruction = [
    'Исправь предыдущий JSON-ответ.',
    '',
    'Сохрани исходную letter_strategy.',
    '',
    'Если letter_strategy=omit:',
    '- верни пустой cover_letter;',
    '- верни пустой facts_used;',
    '- не составляй письмо.',
    '',
    'Если letter_strategy=targeted или bridge:',
    '- cover_letter обязателен и не может быть пустым;',
    '- составь законченное письмо объемом 350-650 символов;',
    '- первая содержательная фраза должна говорить о задаче или пользе работодателю;',
    '- не пересказывай резюме;',
    '- используй не более двух фактов;',
    '- не называй AI Content Studio, AICS, MIKISSKIDS или Элиор;',
    '- описывай назначение проекта без собственного названия;',
    '- не используй обобщающие ссылки на предыдущие предложения;',
    '- удали конструкции «этот опыт», «такой опыт», «такой подход», «эти навыки»;',
    '- удали конструкции «это подтверждает», «это показывает», «это дает», «это связано», «это близко»;',
    '- удали конструкции «что подтверждает», «что показывает», «что помогает», «что позволяет», «что пересекается»;',
    '- не заменяй запрещенные конструкции синонимичными мета-выводами;',
    '- не добавляй действия, технологии или обязанности из вакансии, если они отсутствуют в выбранном профиле;',
    '- сохрани employer_need, value_offer и strategy_reason.',
    '',
    'Верни только JSON по исходной Schema.',
  ].join('\n');

  const correctionRequest = {
    ...vacancy.openrouter_request,
    messages: [
      ...vacancy.openrouter_request.messages,
      {
        role: 'assistant',
        content: firstContent,
      },
      {
        role: 'user',
        content: correctionInstruction,
      },
    ],
  };

  response = await sendRequest(correctionRequest);
  vacancy.meta_phrase_retry_performed = true;
} else {
  vacancy.meta_phrase_retry_performed = false;
}

vacancy.openrouter_response = response;

return {
  json: vacancy,
};

const vacancy = { ...$json };
const response = vacancy.openrouter_response;

if (!response || typeof response !== 'object') {
  throw new Error(
    `Missing OpenRouter response for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

const choice = response.choices?.[0];

if (!choice) {
  throw new Error(
    `Missing OpenRouter choice for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

const finishReason = String(choice.finish_reason || '');

if (finishReason === 'length') {
  throw new Error(
    `Truncated cover letter response for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

if (finishReason === 'content_filter') {
  throw new Error(
    `Cover letter response blocked for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

const rawContent = choice.message?.content;

if (typeof rawContent !== 'string' || !rawContent.trim()) {
  throw new Error(
    `Empty cover letter response for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

const cleanedContent = rawContent
  .trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let result;

try {
  result = JSON.parse(cleanedContent);
} catch {
  throw new Error(
    `Invalid cover letter JSON for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

if (
  !result ||
  typeof result !== 'object' ||
  Array.isArray(result)
) {
  throw new Error(
    `Invalid cover letter result for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

const allowedLetterStrategies = new Set([
  'targeted',
  'bridge',
  'omit',
]);

const letterStrategy = String(
  result.letter_strategy || ''
).trim();

if (!allowedLetterStrategies.has(letterStrategy)) {
  throw new Error(
    `Invalid letter_strategy for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }: ${letterStrategy || 'empty'}`
  );
}

const employerNeed = String(
  result.employer_need || ''
).trim().slice(0, 300);

const valueOffer = String(
  result.value_offer || ''
).trim().slice(0, 300);

const strategyReason = String(
  result.strategy_reason || ''
).trim().slice(0, 400);

function normalizePublicText(value) {
  return String(value || '')
    .replace(/\u00a0/g, ' ')
    .replace(/\u21b5/g, '\n')
    .replace(/\r\n?/g, '\n')
    .replace(/[\u2013\u2014\u2212]/g, '-')
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201c\u201d]/g, '"')
    .replace(/\u2022/g, '-')
    .replace(/\u2192/g, '->')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function normalizeList(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((entry) => normalizePublicText(entry))
    .filter(Boolean)
    .slice(0, 5);
}

function normalizeFactsUsed(value) {
  const entries = normalizeList(value);
  const merged = [];

  for (const entry of entries) {
    const previousIndex = merged.length - 1;

    if (
      previousIndex >= 0 &&
      !/[.!?]["')\]]?$/.test(merged[previousIndex])
    ) {
      merged[previousIndex] =
        `${merged[previousIndex]} ${entry}`
          .replace(/\s+/g, ' ')
          .trim();
    } else {
      merged.push(entry);
    }
  }

  return merged.slice(0, 2);
}

function parseAnalysis(value) {
  if (value && typeof value === 'object') {
    return value;
  }

  if (typeof value !== 'string' || !value.trim()) {
    return {};
  }

  try {
    const parsed = JSON.parse(value);

    return parsed && typeof parsed === 'object'
      ? parsed
      : {};
  } catch {
    return {};
  }
}

function cleanupVacancy(value) {
  delete value.openrouter_request;
  delete value.openrouter_response;
  delete value.letter_analysis;
  delete value.letter_recommended_resume;
  delete value.letter_score;
  delete value.letter_decision;
  delete value.letter_blocking_reasons;
  delete value.detected_salary_upper_bound;
  delete value.meta_phrase_retry_performed;
}

const generatedAt = $now.toUTC().toISO();
const analysis = parseAnalysis(vacancy.analysis_json);
const modelWarnings = normalizeList(result.warnings);

if (letterStrategy === 'omit') {
  const finalStrategyReason =
    strategyReason ||
    'Нет убедительного прямого или сильного смежного подтверждения центральной задачи вакансии.';

  analysis.cover_letter_generation = {
    model: String(
      response.model ||
      vacancy.openrouter_request?.model ||
      ''
    ),
    generated_at: generatedAt,
    finish_reason: finishReason,
    facts_used: [],
    warnings: [],
    model_warnings: modelWarnings,
    requires_review: false,
    usage: response.usage || {},
    meta_phrase_retry_performed: Boolean(
      vacancy.meta_phrase_retry_performed
    ),
    letter_strategy: 'omit',
    employer_need: employerNeed,
    value_offer: valueOffer,
    strategy_reason: finalStrategyReason,
  };

  vacancy.cover_letter = '';
  vacancy.status = 'letter_omitted';
  vacancy.updated_at = generatedAt;
  vacancy.analysis_json = JSON.stringify(analysis);
  vacancy.last_error = '';

  cleanupVacancy(vacancy);

  return {
    json: vacancy,
  };
}

function splitIntoSentences(value) {
  return (
    String(value || '').match(
      /[^.!?]+(?:[.!?]+(?:["»])?|$)/g
    ) || []
  )
    .map((sentence) => sentence.trim())
    .filter(Boolean);
}

function splitBalanced(items, groupCount) {
  const groups = [];
  let cursor = 0;

  for (
    let index = 0;
    index < groupCount;
    index += 1
  ) {
    const remainingItems = items.length - cursor;
    const remainingGroups = groupCount - index;
    const groupSize = Math.ceil(
      remainingItems / remainingGroups
    );

    groups.push(
      items
        .slice(cursor, cursor + groupSize)
        .join(' ')
        .trim()
    );

    cursor += groupSize;
  }

  return groups.filter(Boolean);
}

function normalizeCoverLetter(value) {
  let text = normalizePublicText(value);

  text = text
    .replace(
      /\s*(?:С уважением,?\s*)?\[(?:имя|фио|name)\]\.?\s*$/i,
      ''
    )
    .trim();

  text = text
    .replace(/^Здравствуйте!\s*/i, '')
    .trim();

  const sentences = splitIntoSentences(text);

  if (!sentences.length) {
    return '';
  }

  let closingSentence = '';
  const lastSentence = sentences[sentences.length - 1];

  if (
    /^(?:Буду рад|Готов|Открыт|Предлагаю обсудить|С удовольствием обсужу)/i.test(
      lastSentence
    )
  ) {
    closingSentence = sentences.pop();
  } else if (sentences.length >= 3) {
    closingSentence = sentences.pop();
  }

  const contentGroupCount = Math.min(
    2,
    Math.max(1, Math.ceil(sentences.length / 2))
  );

  const contentParagraphs = splitBalanced(
    sentences,
    contentGroupCount
  );

  return [
    'Здравствуйте!',
    ...contentParagraphs,
    closingSentence,
  ]
    .filter(Boolean)
    .join('\n\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const coverLetter = normalizeCoverLetter(
  result.cover_letter || result.letter || ''
);

if (!coverLetter) {
  const emptyLetterWarning =
    `Generation issue: empty cover letter for ${letterStrategy} strategy`;

  analysis.cover_letter_generation = {
    model: String(
      response.model ||
      vacancy.openrouter_request?.model ||
      ''
    ),
    generated_at: generatedAt,
    finish_reason: finishReason,
    facts_used: normalizeFactsUsed(result.facts_used),
    warnings: [emptyLetterWarning],
    model_warnings: modelWarnings,
    requires_review: true,
    usage: response.usage || {},
    meta_phrase_retry_performed: Boolean(
      vacancy.meta_phrase_retry_performed
    ),
    letter_strategy: letterStrategy,
    employer_need: employerNeed,
    value_offer: valueOffer,
    strategy_reason:
      strategyReason ||
      'Модель выбрала стратегию письма, но не сформировала его текст.',
  };

  vacancy.cover_letter = '';
  vacancy.status = 'letter_review';
  vacancy.updated_at = generatedAt;
  vacancy.analysis_json = JSON.stringify(analysis);
  vacancy.last_error = '';

